[
    {
        "title": "先算原盐水含盐量",
        "description": "30% 盐水 200 克，含盐量为 $200\\times30\\%=60$ 克。",
        "bubbleText": "先找盐有多少。原来的盐水里，盐占 $30\\%$，所以盐是 $200\\times30\\%=60$ 克。",
        "bubblePos": {
            "x": 170,
            "y": 250
        }
    },
    {
        "title": "列出配制关系",
        "description": "设加入 10% 盐水 $x$ 克，则混合后总质量为 $200+x$ 克，含盐量为 $60+10\\%x$ 克。",
        "bubbleText": "加入的盐水既带来总重量，也带来一些盐。加入 $x$ 克，就增加 $10\\%x$ 克盐。",
        "bubblePos": {
            "x": 410,
            "y": 120
        }
    },
    {
        "title": "求加入量",
        "description": "根据浓度关系列式：$60+10\\%x=22\\%(200+x)$，解得 $x=\\frac{400}{3}=133\\frac{1}{3}$ 克。",
        "bubbleText": "混合后的盐必须占总量的 $22\\%$。把含盐量和总量放进同一个等式，就能求出要加 $133\\frac{1}{3}$ 克。",
        "bubblePos": {
            "x": 650,
            "y": 235
        }
    },
    {
        "title": "倒掉一半",
        "description": "配好后总质量为 $200+133\\frac{1}{3}=333\\frac{1}{3}$ 克，含盐量为 $333\\frac{1}{3}\\times22\\%=73\\frac{1}{3}$ 克。倒掉一半后，剩余总量为 $166\\frac{2}{3}$ 克，剩余盐为 $36\\frac{2}{3}$ 克。",
        "bubbleText": "盐水是均匀的，倒掉一半时，盐和水也各倒掉一半，所以剩下的盐仍然是原来的一半。",
        "bubblePos": {
            "x": 605,
            "y": 250
        }
    },
    {
        "title": "加水降到15%",
        "description": "设加入纯水 $y$ 克。纯水不含盐，因此列式：$\\frac{36\\frac{2}{3}}{166\\frac{2}{3}+y}=15\\%$，解得 $y=77\\frac{7}{9}$ 克。",
        "bubbleText": "加水只会增加总重量，不会增加盐。让原有的 $36\\frac{2}{3}$ 克盐占新总量的 $15\\%$，就能算出加水量。",
        "bubblePos": {
            "x": 400,
            "y": 505
        }
    },
    {
        "title": "验证最终浓度",
        "description": "加水后总质量为 $166\\frac{2}{3}+77\\frac{7}{9}=244\\frac{4}{9}$ 克，浓度为 $\\frac{36\\frac{2}{3}}{244\\frac{4}{9}}=15\\%$，答案正确。",
        "bubbleText": "最后检查一次：盐还是 $36\\frac{2}{3}$ 克，总量变成 $244\\frac{4}{9}$ 克，盐占 $15\\%$，所以结果正确。",
        "bubblePos": {
            "x": 400,
            "y": 145
        }
    }
]
